def gen(rng):

    def build(n, rng, mode, cap=2400):
        # returns parent list (index 0 is the root), depth <= cap
        par = [-1] * n
        dep = [0] * n
        for i in range(1, n):
            if mode == "path" and i <= cap:
                p = i - 1
            elif mode == "star":
                p = 0
            elif mode == "binary":
                p = (i - 1) // 2
            elif mode == "cater":
                p = i - 1 if i <= 1000 else rng.randrange(1000)
            else:
                p = rng.randrange(i)
                while dep[p] >= cap:
                    p = rng.randrange(i)
            par[i] = p
            dep[i] = dep[p] + 1
        return par

    def edges_of(par, rng, shuffle=True):
        n = len(par)
        lab = list(range(1, n + 1))
        if shuffle:
            rng.shuffle(lab)
        e = [(lab[i], lab[par[i]]) if rng.random() < 0.5 else (lab[par[i]], lab[i]) for i in range(1, n)]
        rng.shuffle(e)
        return e

    PR = [1, 2, 6, 30, 210, 2310, 30030, 510510, 9699690, 223092870]

    def val(level):
        p = PR[level]
        return p * rng.randint(1, max(1, min(6, 10**9 // p)))

    def fmt(a, e):
        return str(len(a)) + "\n" + " ".join(map(str, a)) + "\n" + "\n".join(f"{u} {v}" for u, v in e)

    def small(n, mode, levels):
        par = build(n, rng, mode)
        a = [val(rng.choice(levels)) for _ in range(n)]
        return fmt(a, edges_of(par, rng))

    tests = [
        "1\n1", "1\n6", "1\n223092870", "2\n1 1\n1 2", "2\n30 210\n2 1",
        "5\n6 12 4 30 2\n1 2\n2 3\n2 4\n4 5", "4\n30 210 60 7\n1 2\n2 3\n3 4",
        "3\n1000000000 1000000000 1000000000\n1 2\n2 3",
    ]
    for _ in range(14):
        n = rng.randint(2, 12)
        mode = rng.choice(["random", "path", "star", "binary", "cater"])
        tests.append(small(n, mode, [rng.choice([0, 1, 2, 3]) for _ in range(3)] + [9, 8, 5]))
    for _ in range(6):
        n = rng.randint(8, 14)
        tests.append(small(n, "random", [3, 4, 5, 6, 7, 8, 9]))
    # larger cases
    N = 100000
    for mode in ("random", "path", "cater", "binary", "star"):
        par = build(N, rng, mode)
        levels = [9, 9, 9, 9, 8, 7, 5, 3, 1, 0]
        a = [val(rng.choice(levels)) for _ in range(N)]
        tests.append(fmt(a, edges_of(par, rng)))
    # all deepest level, so everything is one component
    par = build(N, rng, "path")
    tests.append(fmt([223092870 * rng.randint(1, 4) for _ in range(N)], edges_of(par, rng)))
    par = build(N, rng, "random")
    tests.append(fmt([10**9] * N, edges_of(par, rng)))
    return tests
